const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const sourcePath = path.join(root, 'agenda-index.json');
const outputPath = path.join(root, 'agenda-index.js');

if (!fs.existsSync(sourcePath)) throw new Error('agenda-index.json non trovato.');
const agendas = JSON.parse(fs.readFileSync(sourcePath, 'utf8'));
const output = [
  '/* Proprietà intellettuale di Francesco Antonio Binetti */',
  '// Generated by scripts/build-agenda-index.js',
  '// Do not edit by hand.',
  `globalThis.AGENDA_INDEX = ${JSON.stringify(agendas, null, 2)};`,
  ''
].join('\n');

fs.writeFileSync(outputPath, output);
console.log(`Wrote agenda-index.js with ${Object.keys(agendas).length} chapter tooltips.`);
